select setmeal.*, category.name as categoryName from setmeal left join category on setmeal.category_id = category.id
and setmeal.name like concat('%', #{dto.name}, '%')
and setmeal.status = #{dto.status}
and setmeal.category_id = #{dto.categoryId}
order by setmeal.update_time desc

select copies,dish.name,image,description
from setmeal_dish join dish on setmeal_dish.dish_id = dish.id
where setmeal_dish.setmeal_id = #{id};

select count(id) from setmeal


        and status = #{status}


        and category_id = #{categoryId}
